//  Datapath unit Ð structural modelmodule Datapath_STR #(parameter dp_width = 8, R2_width = 4)(   output [R2_width -1: 0] count, output E, output Zero, input [dp_width -1: 0] data,      input Load_regs, Shift_left, Incr_R2, clock, reset_b);  supply1 pwr;  supply0 gnd;  wire [dp_width -1: 0] R1_Dbus, R1;  wire [R2_width -1: 0] R2_Dbus;  wire DR1_0, DR1_1, DR1_2, DR1_3, DR1_4, DR1_5, DR1_6, DR1_7;  wire R1_0, R1_1, R1_2, R1_3, R1_4, R1_5, R1_6, R1_7;  wire R2_0, R2_1, R2_2, R2_3;     wire [R2_width -1: 0] R2 = {R2_3, R2_2, R2_1, R2_0};  assign count = {R2_3, R2_2, R2_1, R2_0};  assign R1 = { R1_7, R1_6, R1_5, R1_4, R1_3, R1_2, R1_1, R1_0};  assign DR1_0 = R1_Dbus[0];  assign DR1_1 = R1_Dbus[1];  assign DR1_2 = R1_Dbus[2];  assign DR1_3 = R1_Dbus[3];  assign DR1_4 = R1_Dbus[4];  assign DR1_5 = R1_Dbus[5];  assign DR1_6 = R1_Dbus[6];  assign DR1_7 = R1_Dbus[7];  nor (Zero, R1_0, R1_1, R1_2, R1_3, R1_4, R1_5, R1_6, R1_7);  DFF D_E (E, R1_7, clock, pwr);    DFF DF_0 (R1_0, DR1_0, clock, pwr);		// Disable reset  DFF DF_1 (R1_1, DR1_1, clock, pwr);  DFF DF_2 (R1_2, DR1_2, clock, pwr);  DFF DF_3 (R1_3, DR1_3, clock, pwr);  DFF DF_4 (R1_4, DR1_4, clock, pwr);  DFF DF_5 (R1_5, DR1_5, clock, pwr);  DFF DF_6 (R1_6, DR1_6, clock, pwr);  DFF DF_7 (R1_7, DR1_7, clock, pwr);  DFF_S DR_0 (R2_0, DR2_0, clock, Load_regs);	// Load_regs (set) drives R2 to all ones  DFF_S DR_1 (R2_1, DR2_1, clock, Load_regs);  DFF_S DR_2 (R2_2, DR2_2, clock, Load_regs);  DFF_S DR_3 (R2_3, DR2_3, clock, Load_regs);  assign DR2_0 = R2_Dbus[0];  assign DR2_1 = R2_Dbus[1];  assign DR2_2 = R2_Dbus[2];  assign DR2_3 = R2_Dbus[3];  wire [1: 0] sel = {Shift_left, Load_regs};  wire [dp_width -1: 0] R1_shifted = {R1_6, R1_5, R1_4, R1_3, R1_2, R1_1, R1_0, 1'b0};  wire [R2_width -1: 0] sum = R2 + 4'b0001;  Mux8_4_x_1 M0 (R1_Dbus, R1, data, R1_shifted, R1, sel);  Mux4_2_x_1 M1 (R2_Dbus, R2, sum, Incr_R2);endmodulemodule Mux8_4_x_1 #(parameter dp_width = 8) (output reg [dp_width -1: 0] mux_out,   input [dp_width -1: 0] in0, in1, in2, in3, input [1: 0] sel);  always @ (in0, in1, in2, in3, sel)    case (sel)      2'b00:	mux_out = in0;      2'b01:	mux_out = in1;      2'b10:	mux_out = in2;      2'b11:	mux_out = in3;    endcaseendmodulemodule Mux4_2_x_1 #(parameter dp_width = 4) (output [dp_width -1: 0] mux_out,   input [dp_width -1: 0] in0, in1, input  sel);  assign mux_out = sel ? in1: in0;endmodule// Test Plan for Datapath Unit:// Demonstrate action of Load_regs// 	R1 gets data, R2 gets all ones// Demonstrate action of Incr_R2// Demonstrate action of Shift_left and detect E// Test bench for datapathmodule t_Datapath_Unit #(parameter dp_width = 8, R2_width = 4)( );  wire [R2_width -1: 0] 	count;  wire 						E, Zero;  reg [dp_width -1: 0] 	data;   reg 						Load_regs, Shift_left, Incr_R2, clock, reset_b;  Datapath_STR M0 (count, E, Zero, data, Load_regs, Shift_left, Incr_R2, clock, reset_b);  initial #250 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin reset_b = 0; #2 reset_b = 1; end  initial fork    data = 8'haa;    Load_regs = 0;    Incr_R2 = 0;    Shift_left = 0;    #10 Load_regs = 1;    #20 Load_regs = 0;    #50 Incr_R2 = 1;    #120 Incr_R2 = 0;    #90 Shift_left = 1;    #200 Shift_left = 0;  joinendmodule// Integrated systemmodule Count_Ones_Gates_1_Hot_STR# (parameter dp_width = 8, R2_width = 4)(   output [R2_width -1: 0] 	count,   input [dp_width -1: 0] 	data,    input 			Start, clock, reset_b);  wire	Load_regs, Incr_R2, Shift_left, Zero, E;  Controller_Gates_1Hot M0 (Ready, Load_regs, Incr_R2, Shift_left, Start, Zero, E, clock, reset_b);  Datapath_STR M1 (count, E, Zero, data, Load_regs, Shift_left, Incr_R2, clock, reset_b);endmodule// Test plan for integrated system// Test for data values of 8'haa, 8'h00, 8'hff.// Test bench for integrated systemmodule t_count_Ones_Gates_1_Hot_STR ();  parameter dp_width = 8, R2_width = 4;  wire [R2_width -1: 0] count;  reg [dp_width -1: 0] data;    reg Start, clock, reset_b;  wire [3: 0] state = {M0.M0.T3, M0.M0.T2, M0.M0.T1, M0.M0.T0};  Count_Ones_Gates_1_Hot_STR M0 (count, data, Start, clock, reset_b);  initial #700 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin reset_b = 0; #2 reset_b = 1; end  initial fork    data = 8'haa;		// Expect count = 4    Start = 0;    #20 Start = 1;	    #30 Start = 0;    #40 data = 8'b00;	// Expect count = 0    #250 Start = 1;    #260 Start = 0;    #280 data = 8'hff;    #280 Start = 1;    #290 Start = 0;  joinendmodule